18	export function Zahl({ wert, stellen = 0, prefix = "", suffix = "", className, dauer = 520 }) {
19	  const ziel = Number.isFinite(wert) ? wert : 0;
20	  const [anzeige, setAnzeige] = useState(ziel);
21	  const aktuell = useRef(ziel);
22	
23	  useEffect(() => {
24	    if (bewegungReduziert()) {
25	      aktuell.current = ziel;
26	      setAnzeige(ziel);
27	      return;
28	    }
29	    const von = aktuell.current;
30	    if (Math.abs(von - ziel) < 1e-9) return;
31	    let raf;
32	    const start = performance.now();
33	    const schritt = (t) => {
34	      const p = Math.min((t - start) / dauer, 1);
35	      const e = 1 - Math.pow(1 - p, 3);
36	      const v = von + (ziel - von) * e;
37	      aktuell.current = v;
38	      setAnzeige(v);
39	      if (p < 1) raf = requestAnimationFrame(schritt);
40	    };
41	    raf = requestAnimationFrame(schritt);
42	    return () => cancelAnimationFrame(raf);
43	  }, [ziel, dauer]);
44	
45	  if (!Number.isFinite(wert)) return <span className={cn("ov-num", className)}>–</span>;
46	  return (
47	    <span className={cn("ov-num", className)}>
