172	/** Beobachtet die Breite eines Elements (für Diagramme ohne Skalierung der Schrift). */
173	export function useBreite(standard = 720) {
174	  const ref = useRef(null);
175	  const [breite, setBreite] = useState(standard);
176	  useEffect(() => {
177	    const el = ref.current;
178	    if (!el) return;
179	    const ro = new ResizeObserver(([e]) => {
180	      const w = Math.round(e.contentRect.width);
181	      if (w > 0) setBreite(w);
182	    });
183	    ro.observe(el);
184	    return () => ro.disconnect();
185	  }, []);
186	  return [ref, breite];
187	}
