      </Section>

      {/* ---------------- Technik & Sicherheit ---------------- */}
      <Section tone="sand" space="lg">
        <div className="grid gap-12 lg:grid-cols-2 lg:gap-16">
          <div>
            <SectionHeading eyebrow="Technik" title="LFP, 2 oder 4 Stunden." />
            <dl className="mt-8 space-y-4">
