});

const toolById = (id) => TOOLS.find((t) => t.id === id);

const GRUPPEN = [
  { titel: "Flächeneigentümer & Landwirte", text: "Eignet sich Ihre Fläche – und was bringt sie über 30 Jahre?", ids: ["flaechencheck", "pacht", "agri-pv"] },
